generated_qss:
QMainWindow, QWidget { background-color: #262624; color: #F5F4EE; font-size: 10pt; }

QGroupBox {
    border: 1px solid #46453F;
    border-radius: 4px;
    margin-top: 8px;
    padding-top: 0px;
    font-weight: bold;
    color: #C96442;
}
QGroupBox::title {
    subcontrol-origin: margin;
    left: 8px;
    padding: 0 4px;
}

QTabWidget::pane
{
    border: 1px solid #46453F;
    top: -1px;
}

QTabBar::tab
{
    background-color: #2F2E2B;
    color: #F5F4EE;
    padding: 6px 12px;
    border: 1px solid #46453F;
    border-top-left-radius: 4px;
    border-top-right-radius: 4px;
    min-width: 70px;
}

QTabBar::tab:selected
{
    background-color: #3A3936;
    color: #C96442;
    font-weight: 600;
    margin-bottom: 0px;
}

QTabBar::tab:hover
{
    background-color: #C96442;
    color: #1F1E1C;
}

QTabBar::tab:!selected
{
    margin-top: 2px;
}

QListWidget { background-color: #2F2E2B; }
QListWidget::item:selected { background-color: #C96442; color: #1F1E1C; }

QTableView {
    background-color: #2F2E2B;
    alternate-background-color: #262624;
    color: #F5F4EE;
    gridline-color: #46453F;
    selection-background-color: #3A3936;
}
QHeaderView::section {
    background-color: #3A3936;
    color: #C96442;
    border: 1px solid #46453F;
    padding: 3px;
    font-weight: bold;
}
QTableWidget {
    background-color: #2F2E2B;
    color: #F5F4EE;
    gridline-color: #46453F;
}

/* ---- Global input sizing ---------------------------------------------- */
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit,
QDateTimeEdit, QPlainTextEdit, QAbstractSpinBox {
    background-color: #3A3936;
    color: #F5F4EE;
    border: 1px solid #46453F;
    border-radius: 3px;
    min-height: 28px;
    padding-top: 4px;
    padding-bottom: 4px;
    padding-left: 4px;
    padding-right: 4px;
}
QComboBox QAbstractItemView {
    background: #3A3936;
    color: #F5F4EE;
    selection-background-color: #C96442;
    selection-color: #1F1E1C;
}
QComboBox QAbstractItemView::item { min-height: 28px; }
QComboBox::drop-down { border: none; min-height: 28px; }

QTextEdit {
    background-color: #2F2E2B;
    color: #F5F4EE;
    border: 1px solid #46453F;
}

QPushButton {
    background-color: #3A3936;
    color: #F5F4EE;
    border: 1px solid #46453F;
    border-radius: 4px;
    padding: 5px 10px;
}
QPushButton:hover { background-color: #C96442; color: #1F1E1C; }
QPushButton:disabled { color: #A8A49A; border-color: #46453F; }

/* ---- Named action buttons (set via objectName) ------------------------ */
QPushButton#btnConnect    { background-color: #5C8A4A;     color: #1F1E1C; font-weight: bold; }
QPushButton#btnDisconnect { background-color: #C0563E;  color: #1F1E1C; }
QPushButton#btnRead       { background-color: #5C8A4A;        color: #1F1E1C; font-weight: bold; }
QPushButton#btnWrite      { background-color: #4A7DA8;       color: #1F1E1C; font-weight: bold; }
QPushButton#btnWriteRead  { background-color: #9A6BB0;  color: #1F1E1C; font-weight: bold; }
QPushButton#btnScan       { background-color: #C9874A;        color: #1F1E1C; font-weight: bold; }
QPushButton#btnApply      { font-weight: bold; }
QPushButton#btnSpyStart   { background-color: #5C8A4A;     color: #1F1E1C; font-weight: bold; font-size: 13px; padding: 6px; }
QPushButton#btnSpyStop    { background-color: #C0563E;  color: #1F1E1C; font-weight: bold; font-size: 13px; padding: 6px; }

QLabel#specgenSectionHeading {
    font-size: 13pt;
    font-weight: 600;
    color: #F5F4EE;
    margin-top: 8px;
    margin-bottom: 4px;
}

QLabel#noteLabel { color: #E0A458; font-size: 10px; }
QLabel#mutedLabel { color: #A8A49A; }
/* [XREF: file-picker] validated file-status line colors */
QLabel#statusOk { color: #7FB069; }
QLabel#statusError { color: #D9785E; }

QPushButton[saveDirty="true"] {
    background-color: #5C8A4A;
    color: #1F1E1C;
    font-weight: 600;
    border-radius: 3px;
    padding: 4px 12px;
}
QPushButton[saveDirty="true"]:hover { background-color: #6B9E57; }

QStatusBar { background-color: #3A3936; color: #F5F4EE; }
QSplitter::handle { background: #46453F; }
QScrollBar:vertical { background: #262624; width: 10px; }
QScrollBar::handle:vertical { background: #46453F; border-radius: 4px; min-height: 20px; }
QCheckBox { color: #F5F4EE; spacing: 5px; }
QRadioButton { color: #F5F4EE; spacing: 6px; }
QProgressDialog { background-color: #262624; color: #F5F4EE; }
